// The accents each language offers.
//
// Generated by tools/gen_types.py from data/accents.json; edit that and run it
// again. An accent is offered only where there is a voice that really exists or a
// rule that holds for a whole vocabulary.

export interface Accent {
  id: string;
  name: string;
  /** The name cut to what a chip beside a transcription holds: the region's code. */
  short: string;
  /** The espeak voice, which is what says a word nothing has a recording of. */
  voice: string;
  /** Whether the core rewrites a standard transcription into this accent. */
  rule: boolean;
  /** Whether a page is read in it throughout: the language's own reading, a rule that
   *  holds for every word, or readings of its own for most words a page uses. An accent
   *  with a few thousand words of its own reads the rest the way the dictionary does. */
  whole: boolean;
  /** How many words it has a reading of its own for, which arrive as a pack. */
  words: number;
  /** What a recording's speaker in this accent is labelled, lowercased with hyphens as
   *  spaces: its tags, the further labels recordings carry, its short name and its
   *  region's code, which a file named en-us-word.ogg carries in its name. */
  heard: string[];
}

export const ACCENTS: Record<string, Accent[]> = {
  de: [{ id: "de", name: "Germany", short: "DE", voice: "de", rule: false, whole: true, words: 0, heard: ["germany", "berlin", "northern germany", "de"] }, { id: "de-at", name: "Austria", short: "AT", voice: "de", rule: true, whole: true, words: 1007, heard: ["austria", "vienna", "at"] }, { id: "de-ch", name: "Switzerland", short: "CH", voice: "de", rule: true, whole: true, words: 420, heard: ["switzerland", "zurich", "bern", "ch"] }],
  en: [{ id: "en-us", name: "American", short: "US", voice: "en-us", rule: true, whole: true, words: 23474, heard: ["general american", "us", "ga", "american", "california", "new york", "midwest", "texas", "inland north"] }, { id: "en-gb", name: "British", short: "GB", voice: "en-gb-x-rp", rule: true, whole: true, words: 4533, heard: ["received pronunciation", "british", "uk", "rp", "england", "southern england", "london", "northern england", "gb"] }, { id: "en-ca", name: "Canadian", short: "CA", voice: "en-us", rule: true, whole: true, words: 2626, heard: ["canada", "canadian", "toronto", "ontario", "ca"] }, { id: "en-au", name: "Australian", short: "AU", voice: "en-au", rule: false, whole: false, words: 3982, heard: ["australian", "au", "australia", "queensland", "new south wales", "victoria", "sydney", "melbourne"] }, { id: "en-gb-scotland", name: "Scottish", short: "SCOT", voice: "en-gb-scotland", rule: false, whole: false, words: 2362, heard: ["scotland", "scottish", "edinburgh", "glasgow", "scot"] }, { id: "en-029", name: "Caribbean", short: "CARIB", voice: "en-029", rule: false, whole: false, words: 0, heard: ["carib"] }],
  es: [{ id: "es", name: "Spain", short: "ES", voice: "es", rule: false, whole: true, words: 0, heard: ["spain", "madrid", "castile", "northern spain", "es"] }, { id: "es-419", name: "Latin America", short: "LATAM", voice: "es-419", rule: true, whole: true, words: 0, heard: ["latin america", "mexico", "colombia", "chile", "peru", "venezuela", "ecuador", "cuba", "latam"] }, { id: "es-ar", name: "Rioplatense", short: "AR", voice: "es-419", rule: true, whole: true, words: 0, heard: ["argentina", "buenos aires", "uruguay", "rioplatense", "ar"] }],
  fr: [{ id: "fr", name: "France", short: "FR", voice: "fr", rule: false, whole: true, words: 0, heard: ["france", "paris", "fr"] }, { id: "fr-ca", name: "Canada", short: "CA", voice: "fr-ca", rule: false, whole: false, words: 0, heard: ["canada", "quebec", "montreal", "ca"] }],
  pt: [{ id: "pt-br", name: "Brazil", short: "BR", voice: "pt-br", rule: false, whole: true, words: 0, heard: ["brazil", "southern brazil", "são paulo", "rio de janeiro", "br"] }, { id: "pt-pt", name: "Portugal", short: "PT", voice: "pt", rule: false, whole: true, words: 54270, heard: ["portugal", "lisbon", "porto", "pt"] }],
  vi: [{ id: "vi", name: "Northern", short: "North", voice: "vi", rule: false, whole: true, words: 0, heard: ["hanoi", "northern vietnam", "north"] }, { id: "vi-vn-x-central", name: "Central", short: "Central", voice: "vi-vn-x-central", rule: false, whole: true, words: 27237, heard: ["huế", "central vietnam", "central"] }],
};

/** What a language offers, which is nothing for most of them. */
export function accentsOf(lang: string): Accent[] {
  return ACCENTS[lang] ?? [];
}

/**
 * Which of a word's recordings a reader reading [lang] in [accent] hears: one whose
 * speaker is labelled as of that accent, or by the region in its file's name; failing
 * that one labelled as of nowhere the language offers; failing that none, so the voice
 * says it in the accent chosen rather than a speaker saying it in another.
 */
export function recordingIn(
  lang: string, accent: string, files: string[], labels: string[]
): string {
  const rows = accentsOf(lang);
  if (rows.length < 2) return files[0] ?? '';
  const of = (index: number) => {
    const region = /^[a-z]{2,3}-([a-z]{2})-/i.exec(files[index])?.[1] ?? '';
    const said = (labels[index] ?? '').split(/[,()]/).concat(region)
      .map((part) => part.trim().toLowerCase().replace(/[-_]/g, ' ')).filter(Boolean);
    return rows.find((row) => said.some((part) => row.heard.includes(part)))?.id ?? '';
  };
  const speakers = files.map((_, index) => of(index));
  const mine = speakers.indexOf(accent);
  if (mine >= 0) return files[mine];
  const nowhere = speakers.indexOf('');
  return nowhere >= 0 ? files[nowhere] : '';
}

/** The voice that says a word in this accent, or the language's own. */
export function voiceOf(lang: string, accent: string): string {
  return accentsOf(lang).find((row) => row.id === accent)?.voice ?? lang;
}

/** The accent a voice really speaks in: the one it is named for, or failing that the
 *  accent asked for where that is spoken by it, or the first that is. espeak has no
 *  Rioplatense or Canadian voice, so what it says for them is Latin American or
 *  American, and a card names that rather than the accent asked for. */
export function spokenIn(lang: string, voice: string, asked: string): string {
  const speaking = accentsOf(lang).filter((row) => row.voice === voice);
  return (
    speaking.find((row) => row.id === voice)?.id ??
    speaking.find((row) => row.id === asked)?.id ??
    speaking[0]?.id ??
    ''
  );
}

/** The accents a page in this language can be read in throughout. */
export function wholeAccentsOf(lang: string): Accent[] {
  return accentsOf(lang).filter((row) => row.whole);
}

/** The accent a language is read in until the reader picks another, or nothing for a
 *  language with no accents to choose between. There is always one where there are
 *  accents: a reading in no accent in particular is a mix of them. */
export function defaultAccentOf(lang: string): string {
  return DEFAULTS[lang] ?? '';
}

const DEFAULTS: Record<string, string> = {
  de: "de",
  en: "en-us",
  es: "es",
  fr: "fr",
  pt: "pt-br",
  vi: "vi",
};
